func Test_StrategyBfsDefaultOrder(t *testing.T) {
	// BFS strategy visits pages in breadth-first order
	var engineConfig pkg.CrawlConfig
	if err := json.Unmarshal([]byte(`{"crawl_strategy":"bfs","max_concurrent":1,"max_depth":2}`), &engineConfig); err != nil {
		t.Fatalf("config parse failed: %v", err)
	}
	engine, createErr := pkg.CreateEngine(&engineConfig)
	if createErr != nil {
		t.Fatalf("create handle failed: %v", createErr)
	}
	url := os.Getenv("MOCK_SERVER_STRATEGY_BFS_DEFAULT_ORDER")
	if url == "" {
		url = os.Getenv("MOCK_SERVER_URL") + "/fixtures/strategy_bfs_default_order"
	}
	result, err := pkg.Crawl(engine, url)
	if err != nil {
		t.Fatalf("call failed: %v", err)
	}
	if len(result.Pages) != 5 {
		t.Errorf("equals mismatch: got %v", len(result.Pages))
	}
	if !strings.Contains(string(result.Pages[1].URL), `alpha`) {
		t.Errorf("expected to contain %s, got %v", `alpha`, result.Pages[1].URL)
	}
	if !strings.Contains(string(result.Pages[2].URL), `beta`) {
		t.Errorf("expected to contain %s, got %v", `beta`, result.Pages[2].URL)
	}
	if !strings.Contains(string(result.Pages[3].URL), `one`) {
		t.Errorf("expected to contain %s, got %v", `one`, result.Pages[3].URL)
	}
	if !strings.Contains(string(result.Pages[4].URL), `two`) {
		t.Errorf("expected to contain %s, got %v", `two`, result.Pages[4].URL)
	}
}

